27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    public String getPostcode() {
58	        return this.postcode;
59	    }
60	
61	    public void setPostcode(String postcode) {
62	        this.postcode = postcode;
63	    }
64	
65	    @Column(name = "registration_date")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "customer_code")
69	    private String customerCode;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "household_size")
75	    private Integer householdSize;
76	
77	    public String getCustomerCode() {
78	        return this.customerCode;
79	    }
80	
81	    public void setCustomerCode(String customerCode) {
82	        this.customerCode = customerCode;
83	    }
84	
85	    public Integer getNamesakeCount() {
86	        return this.namesakeCount;
87	    }
88	
89	    public void setNamesakeCount(Integer namesakeCount) {
90	        this.namesakeCount = namesakeCount;
91	    }
92	
93	    public Integer getHouseholdSize() {
94	        return this.householdSize;
95	    }
96	
97	    public void setHouseholdSize(Integer householdSize) {
98	        this.householdSize = householdSize;
99	    }
100	
101	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
102	    private Set<Pet> pets;
103	
104	    public String getEmail() {
105	        return this.email;
106	    }
107	
108	    public void setEmail(String email) {
109	        this.email = email;
110	    }
111	
112	    public LocalDate getRegistrationDate() {
113	        return this.registrationDate;
114	    }
115	
116	    public void setRegistrationDate(LocalDate registrationDate) {
117	        this.registrationDate = registrationDate;
118	    }
119	
120	    public String getAddress() {
121	        return this.address;
122	    }
123	
124	    public void setAddress(String address) {
125	        this.address = address;
126	    }
127	
128	    public String getCity() {
129	        return this.city;
130	    }
131	
132	    public void setCity(String city) {
133	        this.city = city;
134	    }
135	
136	    public String getTelephone() {
137	        return this.telephone;
138	    }
139	
140	    public void setTelephone(String telephone) {
141	        this.telephone = telephone;
142	    }
143	
144	    protected Set<Pet> getPetsInternal() {
145	        if (this.pets == null) {
146	            this.pets = new HashSet<>();
147	        }
148	        return this.pets;
149	    }
150	
151	    protected void setPetsInternal(Set<Pet> pets) {
152	        this.pets = pets;
153	    }
154	
155	    public List<Pet> getPets() {
156	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
157	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
158	        return Collections.unmodifiableList(sortedPets);
159	    }
160	
161	    public void setPets(List<Pet> pets) {
162	        this.pets = new HashSet<>(pets);
163	    }
164	
165	    public void addPet(Pet pet) {
166	        getPetsInternal().add(pet);
167	        pet.setOwner(this);
168	    }
169	
170	    /**
171	     * Return the Pet with the given name, or null if none found for this Owner.
172	     *
173	     * @param name to test
174	     * @return true if pet name is already in use
175	     */
176	    public Pet getPet(String name) {
177	        return getPet(name, false);
178	    }
179	
180	    /**
181	     * Return the Pet with the given name, or null if none found for this Owner.
182	     *
183	     * @param name to test
184	     * @return true if pet name is already in use
185	     */
186	    public Pet getPet(String name, boolean ignoreNew) {
187	        name = name.toLowerCase();
188	        for (Pet pet : getPetsInternal()) {
189	            if (!ignoreNew || !pet.isNew()) {
190	                String compName = pet.getName();
191	                compName = compName.toLowerCase();
192	                if (compName.equals(name)) {
193	                    return pet;
194	                }
195	            }
196	        }
197	        return null;
198	    }
199	
200	    public Pet getPet(Integer petId) {
201	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
202	    }
203	
204	    @Override
205	    public String toString() {
206	        return new ToStringCreator(this)
207	
208	            .append("id", this.getId())
209	            .append("new", this.isNew())
210	            .append("lastName", this.getLastName())
211	            .append("firstName", this.getFirstName())
212	            .append("address", this.address)
213	            .append("city", this.city)
214	            .append("telephone", this.telephone)
215	            .toString();
216	    }
217	}
