43	        this.ownerRepository = ownerRepository;
44	    }
45	
46	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
47	    public void assignHouseholdSize(Owner owner) {
48	        if (owner.isNew() && owner.getHouseholdSize() == null) {
49	            String household = householdKey(owner);
50	            long existing = ownerRepository.findAll().stream()
51	                .filter(other -> household.equals(householdKey(other)))
52	                .count();
53	            owner.setHouseholdSize((int) (existing + 1));
54	        }
55	    }
56	
57	    private static String householdKey(Owner owner) {
58	        String normalized = (owner.getLastName() + "|" + owner.getAddress())
59	            .trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
60	        return UUID.nameUUIDFromBytes(normalized.getBytes(StandardCharsets.UTF_8)).toString();
61	    }
