17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	
22	/**
23	 * Resolves the effective registration date to a business day: a supplied date is used as-is,
24	 * a missing one defaults to the server's current date, and either way a Saturday or Sunday is
25	 * rolled forward to the following Monday. Kept as one tiny, self-contained unit so every rule
26	 * that depends on the registration date shares the same adjustment without growing a handler.
27	 */
28	final class RegistrationBusinessDay {
29	
30	    private RegistrationBusinessDay() {
31	    }
32	
33	    static LocalDate effective(LocalDate supplied) {
34	        LocalDate date = supplied == null ? LocalDate.now() : supplied;
35	        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
36	            return date.plusDays(2);
37	        }
38	        if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
39	            return date.plusDays(1);
40	        }
41	        return date;
42	    }
43	}
